import{_ as i,o,c as l,a2 as e,j as t,a as r}from"./chunks/framework.C0KMm31j.js";const s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_03_mdp_overview.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_03_markov_history_compression.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_03_transition_probability.png",p="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_03_bellman_backup.png",c="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_03_driving_state_design.png",k=JSON.parse('{"title":"马尔可夫不是“失忆”：一篇看懂强化学习的数学骨架","description":"马尔可夫决策过程经常被讲成一串符号：状态集合、动作集合、转移概率、奖励函数和折扣因子。初学者背完定义，仍然不知道它和真实任务有什么关系。真正重要的不是记住五元组，而是理解它试图回答的问题：智能体掌握的“当前状态”，是否已经足够支撑下一次决策和未来预测？","frontmatter":{"title":"马尔可夫不是“失忆”：一篇看懂强化学习的数学骨架","description":"马尔可夫决策过程经常被讲成一串符号：状态集合、动作集合、转移概率、奖励函数和折扣因子。初学者背完定义，仍然不知道它和真实任务有什么关系。真正重要的不是记住五元组，而是理解它试图回答的问题：智能体掌握的“当前状态”，是否已经足够支撑下一次决策和未来预测？","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":17,"source":"2026-08-13/rl_series_03_markov_decision_process.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_03_mdp_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-03-markov-decision-process"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"马尔可夫不是“失忆”：一篇看懂强化学习的数学骨架"}],["meta",{"property":"og:description","content":"马尔可夫决策过程经常被讲成一串符号：状态集合、动作集合、转移概率、奖励函数和折扣因子。初学者背完定义，仍然不知道它和真实任务有什么关系。真正重要的不是记住五元组，而是理解它试图回答的问题：智能体掌握的“当前状态”，是否已经足够支撑下一次决策和未来预测？"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-03-markov-decision-process"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_03_mdp_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"马尔可夫不是“失忆”：一篇看懂强化学习的数学骨架"}],["meta",{"name":"twitter:description","content":"马尔可夫决策过程经常被讲成一串符号：状态集合、动作集合、转移概率、奖励函数和折扣因子。初学者背完定义，仍然不知道它和真实任务有什么关系。真正重要的不是记住五元组，而是理解它试图回答的问题：智能体掌握的“当前状态”，是否已经足够支撑下一次决策和未来预测？"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_03_mdp_overview.png"}]],"prev":{"text":"别再把状态和观测混为一谈：拆开强化学习的六个核心概念","link":"/rl/rl-series-02-agent-environment-state-action-reward"},"next":{"text":"价值是怎样从终点倒着传回来的？一篇看懂动态规划","link":"/rl/rl-series-04-dynamic-programming"}},"headers":[],"relativePath":"rl/rl-series-03-markov-decision-process.md","filePath":"rl/rl-series-03-markov-decision-process.md","lastUpdated":null}'),d={name:"rl/rl-series-03-markov-decision-process.md"};function _(m,a,u,b,q,$){return o(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="马尔可夫不是-失忆-一篇看懂强化学习的数学骨架" tabindex="-1">马尔可夫不是“失忆”：一篇看懂强化学习的数学骨架 <a class="header-anchor" href="#马尔可夫不是-失忆-一篇看懂强化学习的数学骨架" aria-label="Permalink to &quot;马尔可夫不是“失忆”：一篇看懂强化学习的数学骨架&quot;">​</a></h1><p>马尔可夫决策过程经常被讲成一串符号：状态集合、动作集合、转移概率、奖励函数和折扣因子。初学者背完定义，仍然不知道它和真实任务有什么关系。真正重要的不是记住五元组，而是理解它试图回答的问题：智能体掌握的“当前状态”，是否已经足够支撑下一次决策和未来预测？</p><p><img src="'+s+'" alt="马尔可夫决策过程总览"></p><h2 id="一、结论先说" tabindex="-1">一、结论先说 <a class="header-anchor" href="#一、结论先说" aria-label="Permalink to &quot;一、结论先说&quot;">​</a></h2><p>马尔可夫决策过程（Markov Decision Process，马尔可夫决策过程）是强化学习最常用的问题描述框架。它把一个连续决策任务拆成状态、动作、状态转移、奖励和初始状态分布，并用策略决定在每个状态如何行动。</p><p>马尔可夫性（Markov Property，马尔可夫性质）并不是说系统没有历史，也不是说智能体必须忘掉过去。它要求的是：当当前状态已经给定后，预测下一状态所需的信息不必再从更早历史中寻找。</p><p>如果当前状态遗漏了控制延迟、邻车意图、执行器状态或历史速度趋势，那么“未来只依赖当前状态与动作”就可能不成立。此时问题不在算法，而在状态表示不完整。</p><p>对自动驾驶而言，MDP 最重要的价值不是提供一个漂亮公式，而是强迫建模者明确：策略看见什么、能够做什么、世界如何响应、目标如何评价，以及哪些历史信息必须被压缩进当前决策表示。</p><h2 id="二、从普通随机过程走到决策过程" tabindex="-1">二、从普通随机过程走到决策过程 <a class="header-anchor" href="#二、从普通随机过程走到决策过程" aria-label="Permalink to &quot;二、从普通随机过程走到决策过程&quot;">​</a></h2><h3 id="_2-1-马尔可夫过程只有状态转移" tabindex="-1">2.1 马尔可夫过程只有状态转移 <a class="header-anchor" href="#_2-1-马尔可夫过程只有状态转移" aria-label="Permalink to &quot;2.1 马尔可夫过程只有状态转移&quot;">​</a></h3><p>马尔可夫过程（Markov Process，马尔可夫过程）描述状态如何随机变化。系统从状态 $s_t$ 出发，按照转移概率到达 $s_{t+1}$。其中没有智能体动作，也没有任务收益，过程只是按照自身规律演化。</p><p>天气变化可以被简化为这种过程：已知今天晴天，明天可能继续晴，也可能转阴或下雨。模型关心状态之间如何转移，不讨论谁能控制天气。</p><h3 id="_2-2-马尔可夫奖励过程加入价值判断" tabindex="-1">2.2 马尔可夫奖励过程加入价值判断 <a class="header-anchor" href="#_2-2-马尔可夫奖励过程加入价值判断" aria-label="Permalink to &quot;2.2 马尔可夫奖励过程加入价值判断&quot;">​</a></h3><p>马尔可夫奖励过程（Markov Reward Process，马尔可夫奖励过程）在状态转移之外加入奖励与折扣。系统仍然没有动作选择，但每次到达状态或发生转移时会得到反馈，于是可以评价“从某个状态出发，未来累计回报有多大”。</p><p>它像一只顺流而下的纸船：河道决定下一段流向，纸船无法主动转弯，但不同河段可以对应不同收益或代价。</p><h3 id="_2-3-马尔可夫决策过程加入可控动作" tabindex="-1">2.3 马尔可夫决策过程加入可控动作 <a class="header-anchor" href="#_2-3-马尔可夫决策过程加入可控动作" aria-label="Permalink to &quot;2.3 马尔可夫决策过程加入可控动作&quot;">​</a></h3><p>MDP 比马尔可夫奖励过程多了决策层。智能体在状态 $s_t$ 选择动作 $a_t$，环境再根据状态与动作共同决定下一状态分布和奖励。</p><p>纸船上现在多了一位可以划桨的人。水流仍然带来随机性，但动作会改变接下来更可能到达哪里。强化学习研究的核心也由“这个状态值多少”扩展为“在这个状态应该怎么做”。</p><h2 id="三、马尔可夫性到底在说什么" tabindex="-1">三、马尔可夫性到底在说什么 <a class="header-anchor" href="#三、马尔可夫性到底在说什么" aria-label="Permalink to &quot;三、马尔可夫性到底在说什么&quot;">​</a></h2><h3 id="_3-1-条件概率定义" tabindex="-1">3.1 条件概率定义 <a class="header-anchor" href="#_3-1-条件概率定义" aria-label="Permalink to &quot;3.1 条件概率定义&quot;">​</a></h3><p>对状态序列而言，马尔可夫性可以写成：</p><p>$$ P(s_{t+1}|s_t,a_t,s_{t-1},a_{t-1},\\ldots)=P(s_{t+1}|s_t,a_t) $$</p><p>等式左侧使用完整历史，右侧只保留当前状态与动作。如果二者对下一状态给出相同分布，那么当前状态就是关于未来预测的充分摘要。</p><p><img src="'+n+'" alt="马尔可夫状态压缩历史"></p><h3 id="_3-2-未来并非与过去毫无关系" tabindex="-1">3.2 未来并非与过去毫无关系 <a class="header-anchor" href="#_3-2-未来并非与过去毫无关系" aria-label="Permalink to &quot;3.2 未来并非与过去毫无关系&quot;">​</a></h3><p>过去当然影响现在。车辆此前持续制动，导致当前速度下降；邻车此前逐渐靠近车道线，可能暗示其变道意图。马尔可夫性并不否认这些因果关系，而是要求过去的有效影响已经体现在当前状态里。</p><p>如果当前状态包含速度、加速度、横摆角速度、执行器状态和必要的交互表征，那么更早历史可能不再为下一步预测提供额外信息。若只保留位置和速度，却省略制动器滞后，历史控制量仍会影响未来，当前表示就不够马尔可夫。</p><h3 id="_3-3-马尔可夫性依赖状态如何定义" tabindex="-1">3.3 马尔可夫性依赖状态如何定义 <a class="header-anchor" href="#_3-3-马尔可夫性依赖状态如何定义" aria-label="Permalink to &quot;3.3 马尔可夫性依赖状态如何定义&quot;">​</a></h3><p>同一个物理系统可以有不同状态表示。用单帧图像表示摆动中的钟摆，无法判断它正向左还是向右运动；把角速度加入状态，未来运动方向就更容易预测。</p><p>所以，不能脱离状态表示问“这个环境是不是马尔可夫的”。更准确的问题是：“以当前选择的状态表示，这个过程是否近似满足马尔可夫性？”</p><h3 id="_3-4-完全可观测与部分可观测" tabindex="-1">3.4 完全可观测与部分可观测 <a class="header-anchor" href="#_3-4-完全可观测与部分可观测" aria-label="Permalink to &quot;3.4 完全可观测与部分可观测&quot;">​</a></h3><p>当智能体能够得到足够的马尔可夫状态时，可以按 MDP 建模。若真实状态存在，但智能体只能获得有噪声、缺失或遮挡的观测，则更接近部分可观测马尔可夫决策过程（Partially Observable Markov Decision Process，部分可观测马尔可夫决策过程）。</p><p>工程中常用历史窗口、循环网络、状态估计器或 belief state（信念状态）从观测序列中构造决策表征。这是在尝试恢复对未来预测有用的信息，而不是让系统“记得越多越好”。</p><h2 id="四、一个-mdp-包含哪些要素" tabindex="-1">四、一个 MDP 包含哪些要素 <a class="header-anchor" href="#四、一个-mdp-包含哪些要素" aria-label="Permalink to &quot;四、一个 MDP 包含哪些要素&quot;">​</a></h2><h3 id="_4-1-状态空间" tabindex="-1">4.1 状态空间 <a class="header-anchor" href="#_4-1-状态空间" aria-label="Permalink to &quot;4.1 状态空间&quot;">​</a></h3><p>状态空间 $\\mathcal{S}$ 包含任务中所有合法状态。状态可以是有限集合，也可以是高维连续向量。自动驾驶状态可能包含自车运动、道路几何、邻车相对运动和执行器内部量。</p><p>状态空间定义得太粗，会把未来行为不同的情况混在一起；定义得过细，则增加学习与估计难度，还可能引入部署时不可获得的真值。</p><h3 id="_4-2-动作空间" tabindex="-1">4.2 动作空间 <a class="header-anchor" href="#_4-2-动作空间" aria-label="Permalink to &quot;4.2 动作空间&quot;">​</a></h3><p>动作空间 $\\mathcal{A}$ 描述智能体可以选择的动作。它可以是离散的行为决策，也可以是连续的加速度、转角或轨迹参数。</p><p>动作必须与智能体边界一致。如果策略只负责行为层，就不应把底盘真实转角当作它的直接动作；如果策略直接控制车辆，环境就必须建模执行器约束和动力学。</p><h3 id="_4-3-状态转移概率" tabindex="-1">4.3 状态转移概率 <a class="header-anchor" href="#_4-3-状态转移概率" aria-label="Permalink to &quot;4.3 状态转移概率&quot;">​</a></h3><p>状态转移函数 $P(s&#39;|s,a)$ 表示在状态 $s$ 采取动作 $a$ 后，到达下一状态 $s&#39;$ 的概率。</p><p><img src="'+h+'" alt="同一动作对应概率化未来"></p><p>概率并不只来自物理噪声。其他交通参与者反应、感知误差、路面变化和模型未覆盖因素都可能让同一状态动作对产生不同未来。确定性动力学只是转移分布退化成单点的特殊情况。</p><h3 id="_4-4-奖励函数" tabindex="-1">4.4 奖励函数 <a class="header-anchor" href="#_4-4-奖励函数" aria-label="Permalink to &quot;4.4 奖励函数&quot;">​</a></h3><p>奖励函数可以写成 $R(s,a,s&#39;)$，表示从状态 $s$ 采取动作 $a$ 并到达 $s&#39;$ 后得到的即时反馈。部分教材使用 $R(s,a)$，本质上是对可能的下一状态奖励取期望或采用了更简化的定义。</p><p>奖励用于表达优化偏好，不自动等同于安全约束。碰撞、越界等不可接受事件仍应单独报告约束违反指标。</p><h3 id="_4-5-初始状态分布" tabindex="-1">4.5 初始状态分布 <a class="header-anchor" href="#_4-5-初始状态分布" aria-label="Permalink to &quot;4.5 初始状态分布&quot;">​</a></h3><p>初始状态分布 $\\rho_0$ 决定回合从哪里开始。它容易被忽略，却直接决定训练数据覆盖范围。</p><p>如果合流训练永远从同一车速、同一车距开始，策略可能只记住狭窄场景。合理的初始分布应覆盖目标运行域，同时避免用不可能或物理不一致的状态制造虚假难度。</p><h3 id="_4-6-策略把问题连接到行为" tabindex="-1">4.6 策略把问题连接到行为 <a class="header-anchor" href="#_4-6-策略把问题连接到行为" aria-label="Permalink to &quot;4.6 策略把问题连接到行为&quot;">​</a></h3><p>策略 $\\pi(a|s)$ 给出状态下选择各动作的概率。确定性策略对每个状态给出一个动作，随机性策略给出动作分布。</p><p>MDP 描述环境与任务，策略描述智能体在这个任务里怎样行动。更换策略不会改变任务定义，却会改变智能体访问哪些状态和获得怎样的轨迹。</p><h2 id="五、回报为什么需要折扣" tabindex="-1">五、回报为什么需要折扣 <a class="header-anchor" href="#五、回报为什么需要折扣" aria-label="Permalink to &quot;五、回报为什么需要折扣&quot;">​</a></h2><h3 id="_5-1-单步奖励无法评价长期决策" tabindex="-1">5.1 单步奖励无法评价长期决策 <a class="header-anchor" href="#_5-1-单步奖励无法评价长期决策" aria-label="Permalink to &quot;5.1 单步奖励无法评价长期决策&quot;">​</a></h3><p>智能体在时刻 $t$ 之后获得的折扣回报可以写成：</p><p>$$ G_t=r_{t+1}+\\gamma r_{t+2}+\\gamma^2r_{t+3}+\\cdots $$</p><p>单步奖励只评价一次转移，回报把后续奖励聚合起来。一次减速可能牺牲眼前效率，却换来更安全、更平顺的合流；只看即时奖励无法判断这种长期选择。</p><h3 id="_5-2-折扣因子控制有效时间尺度" tabindex="-1">5.2 折扣因子控制有效时间尺度 <a class="header-anchor" href="#_5-2-折扣因子控制有效时间尺度" aria-label="Permalink to &quot;5.2 折扣因子控制有效时间尺度&quot;">​</a></h3><p>折扣因子（Discount Factor，折扣因子）$\\gamma$ 通常位于 $[0,1)$。$\\gamma$ 较小时，较远奖励衰减更快；$\\gamma$ 接近 $1$ 时，智能体更重视长期结果。</p><p>$\\gamma$ 不是简单的“耐心参数”。它还影响无限时域回报是否有限、价值传播距离和学习稳定性。若每个环境步长代表的真实时间不同，同一个 $\\gamma$ 对应的实际时间尺度也不同。</p><h3 id="_5-3-回合结束与连续任务" tabindex="-1">5.3 回合结束与连续任务 <a class="header-anchor" href="#_5-3-回合结束与连续任务" aria-label="Permalink to &quot;5.3 回合结束与连续任务&quot;">​</a></h3><p>有些任务在到达目标或失败后终止，属于 episodic task（回合式任务）；有些控制任务持续运行，属于 continuing task（持续式任务）。二者都能用 MDP 描述，但回报定义、重置方式和评价指标不同。</p><p>把固定时间上限当成任务自然结束，会混淆 <code>truncated</code>（外部截断）与 <code>terminated</code>（任务终止），也可能错误处理被截断状态之后的价值。</p><h2 id="六、价值函数在预测什么" tabindex="-1">六、价值函数在预测什么 <a class="header-anchor" href="#六、价值函数在预测什么" aria-label="Permalink to &quot;六、价值函数在预测什么&quot;">​</a></h2><h3 id="_6-1-状态价值依赖策略" tabindex="-1">6.1 状态价值依赖策略 <a class="header-anchor" href="#_6-1-状态价值依赖策略" aria-label="Permalink to &quot;6.1 状态价值依赖策略&quot;">​</a></h3><p>状态价值函数（State-value Function，状态价值函数）定义为：</p><p>$$ V^\\pi(s)=\\mathbb{E}_\\pi[G_t|s_t=s] $$</p><p>它表示从状态 $s$ 出发，之后一直遵循策略 $\\pi$ 时的期望回报。同一个状态在不同策略下价值不同，因为后续行为不同。</p><p>“离目标更近”不一定意味着价值更大。如果某个近目标状态迫使车辆急刹，而稍远状态保留了平顺合流空间，后者在合理策略下可能更有价值。</p><h3 id="_6-2-动作价值多问了当前动作" tabindex="-1">6.2 动作价值多问了当前动作 <a class="header-anchor" href="#_6-2-动作价值多问了当前动作" aria-label="Permalink to &quot;6.2 动作价值多问了当前动作&quot;">​</a></h3><p>动作价值函数（Action-value Function，动作价值函数）定义为：</p><p>$$ Q^\\pi(s,a)=\\mathbb{E}_\\pi[G_t|s_t=s,a_t=a] $$</p><p>它表示在状态 $s$ 先执行动作 $a$，之后遵循策略 $\\pi$ 时的期望回报。比较同一状态下不同动作的 $Q$ 值，就能分析当前动作的长期影响。</p><h3 id="_6-3-价值不是已经得到的奖励" tabindex="-1">6.3 价值不是已经得到的奖励 <a class="header-anchor" href="#_6-3-价值不是已经得到的奖励" aria-label="Permalink to &quot;6.3 价值不是已经得到的奖励&quot;">​</a></h3><p>价值是对未来回报的期望，不是计分器里的累计奖励，也不是环境直接返回的真值。它需要通过已知模型计算，或从采样轨迹中估计。</p><p>环境给奖励，智能体学习价值。把二者混为一谈，会误以为只要奖励函数已知，最优行为就自然已知。</p><h2 id="七、贝尔曼方程为什么重要" tabindex="-1">七、贝尔曼方程为什么重要 <a class="header-anchor" href="#七、贝尔曼方程为什么重要" aria-label="Permalink to &quot;七、贝尔曼方程为什么重要&quot;">​</a></h2><h3 id="_7-1-把长期价值拆成一步与未来" tabindex="-1">7.1 把长期价值拆成一步与未来 <a class="header-anchor" href="#_7-1-把长期价值拆成一步与未来" aria-label="Permalink to &quot;7.1 把长期价值拆成一步与未来&quot;">​</a></h3><p>贝尔曼期望方程（Bellman Expectation Equation，贝尔曼期望方程）的核心思想可以写成：</p>',80),t("p",null,[r("$$ V^\\pi(s)=\\mathbb{E}"),t("em",{"t+1":""},"\\pi[r"),r("+\\gamma V^\\pi(s_{t+1})|s_t=s] $$")],-1),e('<p>当前状态的长期价值，等于下一步即时奖励，加上折扣后的下一状态价值。这把一条可能很长的轨迹递归地拆成了“一步结果＋剩余问题”。</p><p><img src="'+p+'" alt="贝尔曼一步递归"></p><h3 id="_7-2-自举既高效也可能传播误差" tabindex="-1">7.2 自举既高效也可能传播误差 <a class="header-anchor" href="#_7-2-自举既高效也可能传播误差" aria-label="Permalink to &quot;7.2 自举既高效也可能传播误差&quot;">​</a></h3><p>使用当前价值估计去更新另一个价值估计，称为 bootstrapping（自举）。它不必等到完整回合结束就能学习，效率很高。</p><p>但若后继状态价值估计偏差很大，误差也会被传播。函数逼近、离策略数据和自举结合时尤其需要关注稳定性，后续 DQN（深度 Q 网络）中的目标网络等技巧正是围绕这些问题展开。</p><h3 id="_7-3-最优方程多了动作选择" tabindex="-1">7.3 最优方程多了动作选择 <a class="header-anchor" href="#_7-3-最优方程多了动作选择" aria-label="Permalink to &quot;7.3 最优方程多了动作选择&quot;">​</a></h3><p>贝尔曼最优方程把固定策略下的期望替换为对动作的最优选择：</p><p>$$ V^<em>(s)=\\max_a\\mathbb{E}[r_{t+1}+\\gamma V^</em>(s_{t+1})|s_t=s,a_t=a] $$</p><p>它表达的是：最优状态价值等于当前选择最佳动作后获得的一步奖励与未来最优价值。这个递归关系是价值迭代、Q-learning 和许多价值型算法的共同骨架。</p><h2 id="八、预测问题与控制问题" tabindex="-1">八、预测问题与控制问题 <a class="header-anchor" href="#八、预测问题与控制问题" aria-label="Permalink to &quot;八、预测问题与控制问题&quot;">​</a></h2><h3 id="_8-1-预测评估已有策略" tabindex="-1">8.1 预测评估已有策略 <a class="header-anchor" href="#_8-1-预测评估已有策略" aria-label="Permalink to &quot;8.1 预测评估已有策略&quot;">​</a></h3><p>给定 MDP 与策略 $\\pi$，求 $V^\\pi$ 或 $Q^\\pi$，属于 prediction（预测）或 policy evaluation（策略评估）。问题是：“如果一直按这套策略行动，它有多好？”</p><h3 id="_8-2-控制寻找更优策略" tabindex="-1">8.2 控制寻找更优策略 <a class="header-anchor" href="#_8-2-控制寻找更优策略" aria-label="Permalink to &quot;8.2 控制寻找更优策略&quot;">​</a></h3><p>给定 MDP，寻找最优策略 $\\pi^*$ 与最优价值函数，属于 control（控制）。问题变成：“应该怎样行动，才能获得更高期望回报？”</p><p>策略迭代（Policy Iteration，策略迭代）会交替进行策略评估和策略改进；价值迭代（Value Iteration，价值迭代）直接围绕贝尔曼最优更新传播价值，再从收敛价值中提取策略。</p><h3 id="_8-3-规划不等于强化学习训练" tabindex="-1">8.3 规划不等于强化学习训练 <a class="header-anchor" href="#_8-3-规划不等于强化学习训练" aria-label="Permalink to &quot;8.3 规划不等于强化学习训练&quot;">​</a></h3><p>当状态转移概率和奖励函数完全已知时，可以直接用动态规划求解，这更接近 planning（规划）。真实强化学习往往不知道完整环境模型，只能通过交互样本学习价值、策略或模型。</p><p>二者使用相同 MDP 语言，却拥有不同信息条件。不能因为价值迭代能求解一个已知网格世界，就认为真实车辆已经可以从少量交互中学会最优驾驶。</p><h2 id="九、自动驾驶状态为何容易不满足马尔可夫性" tabindex="-1">九、自动驾驶状态为何容易不满足马尔可夫性 <a class="header-anchor" href="#九、自动驾驶状态为何容易不满足马尔可夫性" aria-label="Permalink to &quot;九、自动驾驶状态为何容易不满足马尔可夫性&quot;">​</a></h2><h3 id="_9-1-控制延迟保留了历史影响" tabindex="-1">9.1 控制延迟保留了历史影响 <a class="header-anchor" href="#_9-1-控制延迟保留了历史影响" aria-label="Permalink to &quot;9.1 控制延迟保留了历史影响&quot;">​</a></h3><p>如果车辆执行器存在延迟，下一状态不仅由当前观测和新动作决定，也可能由队列中尚未执行的历史命令决定。只把当前转角和车速放进状态，却忽略待执行命令队列，会遗漏未来演化所需信息。</p><h3 id="_9-2-邻车意图通常是隐藏变量" tabindex="-1">9.2 邻车意图通常是隐藏变量 <a class="header-anchor" href="#_9-2-邻车意图通常是隐藏变量" aria-label="Permalink to &quot;9.2 邻车意图通常是隐藏变量&quot;">​</a></h3><p>两辆邻车即使位置和速度相同，也可能分别处于“准备礼让”和“准备加速封堵”的内部意图。当前几何观测相同，未来反应却不同，说明可见量不一定构成充分状态。</p><h3 id="_9-3-单帧感知难以表达运动趋势" tabindex="-1">9.3 单帧感知难以表达运动趋势 <a class="header-anchor" href="#_9-3-单帧感知难以表达运动趋势" aria-label="Permalink to &quot;9.3 单帧感知难以表达运动趋势&quot;">​</a></h3><p>单帧目标列表给出位置，却可能无法可靠判断加速度、横向移动趋势和交互意图。历史轨迹、滤波状态和预测分布能够补充动态信息。</p><h3 id="_9-4-路径参考也可能随上游变化" tabindex="-1">9.4 路径参考也可能随上游变化 <a class="header-anchor" href="#_9-4-路径参考也可能随上游变化" aria-label="Permalink to &quot;9.4 路径参考也可能随上游变化&quot;">​</a></h3><p>如果规划参考线会因上游模块重规划而突然改变，底层控制环境的下一状态就不仅受车辆动作影响，还受未建模的上游状态影响。模块边界外的变化仍然属于环境随机性或隐藏状态，不能假装不存在。</p><h2 id="十、用车道保持检查一个-mdp" tabindex="-1">十、用车道保持检查一个 MDP <a class="header-anchor" href="#十、用车道保持检查一个-mdp" aria-label="Permalink to &quot;十、用车道保持检查一个 MDP&quot;">​</a></h2><h3 id="_10-1-状态需要覆盖动力学与约束" tabindex="-1">10.1 状态需要覆盖动力学与约束 <a class="header-anchor" href="#_10-1-状态需要覆盖动力学与约束" aria-label="Permalink to &quot;10.1 状态需要覆盖动力学与约束&quot;">​</a></h3><p>简化车道保持任务可以使用横向误差、航向误差、车速、道路曲率、当前转角和必要的历史执行状态。若存在转角变化率限制或控制延迟，还应考虑把相关执行器状态或动作队列纳入状态。</p><p><img src="'+c+'" alt="自动驾驶 MDP 状态设计"></p><h3 id="_10-2-动作要与车辆接口一致" tabindex="-1">10.2 动作要与车辆接口一致 <a class="header-anchor" href="#_10-2-动作要与车辆接口一致" aria-label="Permalink to &quot;10.2 动作要与车辆接口一致&quot;">​</a></h3><p>动作可以是期望转角、转角增量或曲率命令。三种定义对应不同转移模型与约束。若策略输出转角增量，状态里通常需要当前转角；否则相同观测和动作可能产生不同真实命令。</p><h3 id="_10-3-奖励与约束分工" tabindex="-1">10.3 奖励与约束分工 <a class="header-anchor" href="#_10-3-奖励与约束分工" aria-label="Permalink to &quot;10.3 奖励与约束分工&quot;">​</a></h3><p>跟踪误差、控制平滑和进度可以进入奖励；道路边界、转角极限和稳定性要求则应形成独立约束或评价指标。把越界只写成有限惩罚，不等于得到安全保证。</p><h3 id="_10-4-初始分布决定策略见过什么" tabindex="-1">10.4 初始分布决定策略见过什么 <a class="header-anchor" href="#_10-4-初始分布决定策略见过什么" aria-label="Permalink to &quot;10.4 初始分布决定策略见过什么&quot;">​</a></h3><p>训练初始状态应覆盖左右横向误差、正负航向误差、不同曲率、速度与延迟条件。评估还需要包含训练分布边界和未见组合，才能判断策略是否只是记住局部区域。</p><h2 id="十一、常见误解" tabindex="-1">十一、常见误解 <a class="header-anchor" href="#十一、常见误解" aria-label="Permalink to &quot;十一、常见误解&quot;">​</a></h2><h3 id="_11-1-马尔可夫等于忘记过去" tabindex="-1">11.1 马尔可夫等于忘记过去 <a class="header-anchor" href="#_11-1-马尔可夫等于忘记过去" aria-label="Permalink to &quot;11.1 马尔可夫等于忘记过去&quot;">​</a></h3><p>错误。马尔可夫状态是对相关历史的充分摘要，而不是删除历史影响。如果过去仍提供额外预测信息，说明状态表示可能不完整。</p><h3 id="_11-2-状态必须是环境全部物理变量" tabindex="-1">11.2 状态必须是环境全部物理变量 <a class="header-anchor" href="#_11-2-状态必须是环境全部物理变量" aria-label="Permalink to &quot;11.2 状态必须是环境全部物理变量&quot;">​</a></h3><p>不一定。状态需要对当前任务的未来预测足够，而不是复制宇宙的所有信息。与任务无关的变量没有必要加入。</p><h3 id="_11-3-mdp-五元组确定后算法就会成功" tabindex="-1">11.3 MDP 五元组确定后算法就会成功 <a class="header-anchor" href="#_11-3-mdp-五元组确定后算法就会成功" aria-label="Permalink to &quot;11.3 MDP 五元组确定后算法就会成功&quot;">​</a></h3><p>五元组只是形式。状态泄露真值、转移模型失真、奖励存在漏洞或初始分布过窄，都会让形式正确的 MDP 得出无效结论。</p><h3 id="_11-4-折扣因子越大越有远见" tabindex="-1">11.4 折扣因子越大越有远见 <a class="header-anchor" href="#_11-4-折扣因子越大越有远见" aria-label="Permalink to &quot;11.4 折扣因子越大越有远见&quot;">​</a></h3><p>不完整。较大的 $\\gamma$ 确实减慢远期奖励衰减，但也增加估计方差、传播距离和训练难度。它还必须结合环境步长和任务时间尺度解释。</p><h3 id="_11-5-最优策略一定唯一" tabindex="-1">11.5 最优策略一定唯一 <a class="header-anchor" href="#_11-5-最优策略一定唯一" aria-label="Permalink to &quot;11.5 最优策略一定唯一&quot;">​</a></h3><p>不一定。多个动作可能具有相同最优价值，最优策略也可能不唯一。最优的含义还严格受奖励和约束定义限制。</p><h2 id="十二、建模时的最小检查表" tabindex="-1">十二、建模时的最小检查表 <a class="header-anchor" href="#十二、建模时的最小检查表" aria-label="Permalink to &quot;十二、建模时的最小检查表&quot;">​</a></h2><ul><li>当前状态是否包含预测下一状态所需的信息。</li><li>过去历史在给定当前状态后是否仍显著提升预测能力。</li><li>状态变量在部署时能否获得，还是仅为仿真真值。</li><li>动作经过哪些限幅、延迟、安全过滤和动力学环节。</li><li>转移随机性来自物理噪声、其他参与者还是模型遗漏。</li><li>奖励表达哪些偏好，哪些安全要求必须独立约束。</li><li>初始状态分布是否覆盖目标运行域。</li><li>回合为何结束，终止与截断是否分开。</li><li>当前任务是已知模型下的规划，还是未知模型下的学习。</li></ul><p>这份检查表的核心只有一句话：MDP 不是给已有代码补一层数学包装，而是用来检验问题定义是否闭合。</p><h2 id="十三、接下来进入动态规划" tabindex="-1">十三、接下来进入动态规划 <a class="header-anchor" href="#十三、接下来进入动态规划" aria-label="Permalink to &quot;十三、接下来进入动态规划&quot;">​</a></h2><p>理解 MDP 后，下一步不是立刻训练神经网络，而是先在一个小型、模型已知的环境里学习怎样求解它。</p><p>下一篇将拆解策略评估、策略改进、策略迭代和价值迭代。重点不只是写出更新公式，还会用一个网格世界解释价值如何从终点向外传播，以及为什么“知道环境模型”与“只能采样交互”会导向不同算法。</p><h2 id="十四、结语" tabindex="-1">十四、结语 <a class="header-anchor" href="#十四、结语" aria-label="Permalink to &quot;十四、结语&quot;">​</a></h2><p>马尔可夫决策过程的真正作用，是把连续决策问题压缩成可讨论、可计算、可验证的结构。</p><p>状态是历史的任务相关摘要，动作让智能体影响未来，转移概率描述不确定世界，奖励定义优化方向，策略产生行为，价值函数则把眼前选择与长期后果连接起来。</p><p>如果状态表示不充分，再强的算法也只能在缺失信息上做最优决策；如果奖励和约束定义错了，求得越精确，偏离真实目标越稳定。数学骨架不会替我们完成建模，但会让建模错误无处藏身。</p><h2 id="十五、资料来源" tabindex="-1">十五、资料来源 <a class="header-anchor" href="#十五、资料来源" aria-label="Permalink to &quot;十五、资料来源&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter2/chapter2.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 2 章“马尔可夫决策过程”原始文档</a></p><p><a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro.html" target="_blank" rel="noreferrer">OpenAI Spinning Up（OpenAI 强化学习入门资料）核心概念与 MDP 定义</a></p><p><a href="https://mitpress.mit.edu/9780262039246/reinforcement-learning/" target="_blank" rel="noreferrer">MIT Press（麻省理工学院出版社）《Reinforcement Learning: An Introduction》2nd edition（第 2 版）页面</a></p><p>本项目强化学习基础概念笔记 -- 项目内 <code>docs/rl_basic_concepts.md</code></p><p>本项目车道保持任务定义 -- 项目内 <code>docs/task_definition_lane_keeping.md</code></p><blockquote><p>版权说明：本文基于公开资料与本项目实验经验重新组织，示意图均为本篇原创绘制，不复刻《蘑菇书》原文插图。</p></blockquote>',65)])])}const f=i(d,[["render",_]]);export{k as __pageData,f as default};
